s=s.replace("<a class=\"side-link {% if request.endpoint == 'student.search' %}active{% endif %}\" href=\"{{url_for('student.search')}}\"><span class=\"nav-icon\"><img src=\"{{ url_for('static',filename='icons/ui/search.svg') }}\" alt=\"\"></span><b>Buscar</b></a>", "<a class=\"side-link {% if request.endpoint == 'student.search' %}active{% endif %}\" href=\"{{url_for('student.search')}}\"><span class=\"nav-icon\"><img src=\"{{ url_for('static',filename='icons/ui/search.svg') }}\" alt=\"\"></span><b>Buscar</b></a>\n    <a class=\"side-link {% if request.endpoint == 'student.profile' %}active{% endif %}\" href=\"{{url_for('student.profile')}}\"><span class=\"nav-icon\"><img src=\"{{ url_for('static',filename='icons/ui/users.svg') }}\" alt=\"\"></span><b>Meu perfil</b></a>")
